  CDN_flop \ptr_clx_r_reg[4] (.clk (i_clk), .d (i_ptr[4]), .sena
       (1'b1), .aclr (n_49), .apre (1'b0), .srl (1'b0), .srd (1'b0), .q
       (ptr_clx_r[4]));
